🟡 **Medium** `service-worker-utils.js:12`

`fetchJournalCached` returns stale cached data when `journalUrl` changes because the cache only checks `CACHE_TTL_MS`, not which URL the cached content came from. If the user updates `journalUrl` in settings, the function returns content from the previous URL until the cache expires. Consider storing and comparing `journalUrl` in the cache entry.

```diff
   async function fetchJournalCached(journalUrl) {
     if (!journalUrl) return null;

     const now = Date.now();
-    if (journalCache && (now - journalCache.fetchedAt) < CACHE_TTL_MS) {
+    if (journalCache && journalCache.url === journalUrl && (now - journalCache.fetchedAt) < CACHE_TTL_MS) {
       return journalCache.text;
     }

     try {
       const response = await fetch(journalUrl, { cache: 'no-store' });
       if (!response.ok) {
         console.warn('[journal-blocker] Journal fetch returned', response.status);
         return null;
       }
       const text = await response.text();
-      journalCache = { text, fetchedAt: now };
+      journalCache = { url: journalUrl, text, fetchedAt: now };
       return text;
```


